// Convierte la respuesta con forma fija del scout en una página.
// En pantalla ancha, dos columnas: las tres ideas a la vista y, al lado, lo que ya existe.
// En el celular, una sola columna con las ideas primero. Todo va adentro, sin pedir nada afuera.

// Todo texto que viene de afuera pasa por acá antes de entrar al HTML.
function esc(s) {
  return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}
// Solo enlaces web de verdad.
function enlaceSeguro(url) {
  return /^https?:\/\//i.test(String(url || '')) ? String(url) : ''
}
function enlace(url, texto) {
  const u = enlaceSeguro(url)
  return u ? '<a href="' + esc(u) + '" target="_blank" rel="noopener">' + esc(texto) + '</a>' : esc(texto)
}
function lista(x) {
  return Array.isArray(x) ? x.filter(function (e) { return e && typeof e === 'object' }) : []
}
// Un SVG chico como imagen de fondo, sin pedir nada afuera.
function svgUrl(svg) {
  return 'url("data:image/svg+xml,' + encodeURIComponent(svg).replace(/\(/g, '%28').replace(/\)/g, '%29').replace(/'/g, '%27') + '")'
}

const CIRCUITO = svgUrl("<svg xmlns='http://www.w3.org/2000/svg' width='440' height='260' viewBox='0 0 440 260' fill='none' stroke='#4DA3FF' stroke-opacity='0.32' stroke-width='2'><path d='M0 70H120L160 30H330'/><path d='M44 0V150L84 190V260'/><path d='M0 210H40'/><circle cx='330' cy='30' r='5' fill='#070A0F'/><circle cx='84' cy='190' r='5' fill='#070A0F'/><circle cx='40' cy='210' r='4' fill='#070A0F'/><circle cx='120' cy='70' r='3' fill='#4DA3FF' fill-opacity='0.5'/></svg>")
const CIRCUITO_ABAJO = svgUrl("<svg xmlns='http://www.w3.org/2000/svg' width='440' height='260' viewBox='0 0 440 260' fill='none' stroke='#4DA3FF' stroke-opacity='0.32' stroke-width='2'><path d='M440 190H320L280 230H110'/><path d='M396 260V110L356 70V0'/><path d='M440 50H400'/><circle cx='110' cy='230' r='5' fill='#070A0F'/><circle cx='356' cy='70' r='5' fill='#070A0F'/><circle cx='400' cy='50' r='4' fill='#070A0F'/><circle cx='320' cy='190' r='3' fill='#4DA3FF' fill-opacity='0.5'/></svg>")

const estilo = `
html, body { margin: 0; background: #070A0F; }
body { color: #F5F7FF; font-family: "Segoe UI", "Segoe UI Variable", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif; font-weight: 700; line-height: 1.3; display: block; min-height: 100vh; -webkit-text-size-adjust: 100%; }
.cielo, .cielo::before, .cielo::after { position: fixed; top: 0; right: 0; bottom: 0; left: 0; pointer-events: none; }
.cielo { z-index: 0; opacity: 0.6; background-image:
  radial-gradient(1.6px 1.6px at 24px 36px, rgba(245,247,255,0.8), transparent),
  radial-gradient(1.2px 1.2px at 170px 96px, rgba(245,247,255,0.6), transparent),
  radial-gradient(1.6px 1.6px at 96px 180px, rgba(154,163,184,0.8), transparent),
  radial-gradient(1.2px 1.2px at 230px 236px, rgba(245,247,255,0.5), transparent),
  radial-gradient(2px 2px at 64px 280px, rgba(242,230,58,0.45), transparent);
  background-size: 250px 250px, 310px 310px, 270px 270px, 340px 340px, 420px 420px; }
.cielo::before { content: ""; background: ${CIRCUITO} left top no-repeat; background-size: 440px 260px; }
.cielo::after { content: ""; background: ${CIRCUITO_ABAJO} right bottom no-repeat; background-size: 440px 260px; }
.escena { position: relative; z-index: 1; box-sizing: border-box; max-width: 1800px; min-height: 100vh; margin: 0 auto; padding: 40px 64px 22px; display: flex; flex-direction: column; }
.chip { display: inline-block; align-self: flex-start; margin: 0; padding: 7px 20px; border: 2px solid rgba(154,163,184,0.55); border-radius: 999px; color: #F5F7FF; font-size: 22px; }
h1 { margin: 16px 0 0; max-width: 1640px; color: #F2E63A; font-size: 38px; font-size: clamp(28px, 2.5vw, 48px); line-height: 1.12; overflow-wrap: anywhere; }
.rejilla { display: flex; flex-wrap: wrap; align-items: flex-start; gap: 24px 44px; margin-top: 24px; }
.ideas { flex: 1 1 940px; min-width: 0; }
.existe { flex: 1 1 520px; min-width: 0; }
h2 { margin: 0 0 14px; color: #9AA3B8; font-size: 18px; font-size: clamp(15px, 1.15vw, 22px); letter-spacing: 0.06em; text-transform: uppercase; }
.ideas h2 { color: #FFB547; }
.idea { position: relative; box-sizing: border-box; margin: 0 0 18px; padding: 20px 28px 20px 96px; border: 2px solid #4DA3FF; border-radius: 20px; background: rgba(11,24,56,0.88); box-shadow: 0 0 0 1px rgba(77,163,255,0.18), 0 0 28px rgba(77,163,255,0.22); }
.idea .numero { position: absolute; left: 24px; top: 22px; width: 52px; height: 52px; border-radius: 50%; background: #FFB547; color: #070A0F; font-size: 30px; line-height: 52px; text-align: center; box-shadow: 0 0 18px rgba(255,181,71,0.5); }
.idea h3 { margin: 0; color: #F5F7FF; font-size: 30px; font-size: clamp(22px, 1.95vw, 38px); line-height: 1.15; }
.idea p { margin: 8px 0 0; font-size: 21px; font-size: clamp(17px, 1.3vw, 25px); line-height: 1.3; }
.idea .hace { color: #F5F7FF; font-weight: 600; }
.idea .paso { color: #F5F7FF; font-weight: 600; }
.idea .paso b { color: #FFB547; font-weight: 700; }
.bloque { margin: 0 0 14px; padding: 14px 22px 6px; border: 2px solid rgba(77,163,255,0.45); border-radius: 18px; background: rgba(14,20,29,0.85); }
.bloque ul { list-style: none; margin: 0; padding: 0; }
.bloque h2 { margin-bottom: 10px; }
.bloque li { position: relative; margin: 0 0 9px; padding-left: 22px; font-size: 17px; font-size: clamp(15px, 0.95vw, 18px); line-height: 1.28; }
.bloque a { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden; }
.apoyo { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bloque li::before { content: ""; position: absolute; left: 0; top: 0.45em; width: 9px; height: 9px; border-radius: 50%; background: #4DA3FF; box-shadow: 0 0 8px rgba(77,163,255,0.8); }
.bloque a { color: #F5F7FF; text-decoration: none; border-bottom: 2px solid rgba(77,163,255,0.7); overflow-wrap: anywhere; }
.apoyo { display: block; margin-top: 2px; color: #9AA3B8; font-weight: 600; font-size: 0.88em; }
.pie { margin: auto 0 0; padding-top: 20px; color: #9AA3B8; font-size: 15px; font-weight: 600; line-height: 1.5; }
.pie span { color: #4DA3FF; }
@keyframes subir { from { opacity: 0; transform: translateY(22px); } to { opacity: 1; transform: none; } }
@keyframes entrar { from { opacity: 0; transform: translateX(-28px) scale(0.98); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: no-preference) {
  .chip, h1 { animation: subir 0.5s ease-out both; }
  .ideas h2 { animation: subir 0.5s ease-out 0.25s both; }
  .idea { animation: entrar 0.55s cubic-bezier(0.2, 0.8, 0.3, 1.1) both; }
  .idea:nth-of-type(1) { animation-delay: 0.45s; }
  .idea:nth-of-type(2) { animation-delay: 0.8s; }
  .idea:nth-of-type(3) { animation-delay: 1.15s; }
  .bloque { animation: subir 0.5s ease-out both; }
  .bloque:nth-of-type(1) { animation-delay: 1.5s; }
  .bloque:nth-of-type(2) { animation-delay: 1.7s; }
  .bloque:nth-of-type(3) { animation-delay: 1.9s; }
}
@media (max-width: 700px) {
  .escena { padding: 24px 16px 18px; }
  .cielo::before, .cielo::after { background-size: 220px 130px; opacity: 0.7; }
  .apoyo { white-space: normal; }
  .chip { font-size: 15px; padding: 5px 14px; }
  h1 { margin-top: 14px; font-size: 26px; }
  .rejilla { margin-top: 22px; gap: 10px; }
  h2 { font-size: 14px; }
  .idea { padding: 16px 16px 16px 68px; border-radius: 16px; }
  .idea .numero { left: 14px; top: 16px; width: 40px; height: 40px; line-height: 40px; font-size: 22px; }
  .idea h3 { font-size: 22px; }
  .idea p { font-size: 17px; }
  .bloque { padding: 14px 16px 4px; }
  .bloque li { font-size: 16px; }
  .pie { font-size: 12px; }
}
`

const r = $input.first().json.output || {}
const yaExiste = lista(r.ya_existe).slice(0, 5)
const paraLeer = lista(r.para_leer).slice(0, 5)
const paraVer = lista(r.para_ver).slice(0, 5)
const ideas = lista(r.ideas).slice(0, 3)

let html = '<style>' + estilo + '</style><div class="cielo" aria-hidden="true"></div><main class="escena">'
html += '<p class="chip">El scout del reto</p>'
html += '<h1>' + esc(r.reto_en_una_frase) + '</h1>'
html += '<div class="rejilla">'
if (ideas.length) {
  html += '<section class="ideas"><h2>Tres ideas para el fin de semana</h2>' + ideas.map(function (e, i) {
    return '<article class="idea"><span class="numero">' + (i + 1) + '</span><h3>' + esc(e.nombre) + '</h3>' +
      '<p class="hace">' + esc(e.que_hace) + '</p>' +
      '<p class="paso"><b>Esta noche:</b> ' + esc(e.primer_paso) + '</p></article>'
  }).join('') + '</section>'
}
let lado = ''
if (yaExiste.length) {
  lado += '<div class="bloque"><h2>Ya existe</h2><ul>' + yaExiste.map(function (e) {
    return '<li>' + enlace(e.enlace, e.nombre) + (e.que_es ? '<span class="apoyo">' + esc(e.que_es) + '</span>' : '') + '</li>'
  }).join('') + '</ul></div>'
}
if (paraLeer.length) {
  lado += '<div class="bloque"><h2>Para leer</h2><ul>' + paraLeer.map(function (e) {
    return '<li>' + enlace(e.enlace, e.titulo) + '</li>'
  }).join('') + '</ul></div>'
}
if (paraVer.length) {
  lado += '<div class="bloque"><h2>Para ver</h2><ul>' + paraVer.map(function (e) {
    return '<li>' + enlace(e.enlace, e.titulo) + (e.canal ? '<span class="apoyo">' + esc(e.canal) + '</span>' : '') + '</li>'
  }).join('') + '</ul></div>'
}
if (lado) html += '<aside class="existe">' + lado + '</aside>'
html += '</div>'
html += '<footer class="pie">Hecho con n8n + SerpApi + IA. Space Talks, NASA Space Apps Santa Cruz 2026. <span>github.com/nema1502/superpoderes-n8n</span></footer>'
html += '</main>'
return [{ json: { html: html, ya_existe: yaExiste.length, para_leer: paraLeer.length, para_ver: paraVer.length, ideas: ideas.length } }]
